<?php
include 'koneksi.php';
$message = ''; $error = false;
if (isset($_GET['hapus'])) {
    $id = (int) $_GET['hapus'];
    $cek = mysqli_prepare($koneksi, 'SELECT COUNT(*) AS jumlah FROM transaksi_detail WHERE barang_id = ?');
    mysqli_stmt_bind_param($cek, 'i', $id); mysqli_stmt_execute($cek); $dipakai = (int) mysqli_stmt_get_result($cek)->fetch_assoc()['jumlah']; mysqli_stmt_close($cek);
    if ($dipakai > 0) { $message = 'Barang tidak dapat dihapus karena masih digunakan pada transaksi.'; $error = true; }
    else { $hapus = mysqli_prepare($koneksi, 'DELETE FROM barang WHERE id = ?'); mysqli_stmt_bind_param($hapus, 'i', $id); mysqli_stmt_execute($hapus); mysqli_stmt_close($hapus); $message = 'Data barang berhasil dihapus.'; }
}
$data = mysqli_query($koneksi, 'SELECT b.*, s.nama AS nama_supplier FROM barang b LEFT JOIN supplier s ON s.id = b.supplier_id ORDER BY b.id');
function rupiahBarang($nilai) { return 'Rp ' . number_format((int) $nilai, 0, ',', '.'); }
?>
<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Data Barang</title><style>body{font-family:Arial,sans-serif;margin:24px;background:#f4f6f8;color:#17202a}main{max-width:1100px;margin:auto}.panel{background:#fff;padding:20px;border:1px solid #d9dee3;border-radius:8px;overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:11px;border-bottom:1px solid #e5e8eb;text-align:left}th{background:#16324f;color:#fff}a{color:#155d8a}.back{display:inline-block;margin-bottom:15px;padding:10px 14px;background:#59636e;color:#fff;text-decoration:none;border-radius:5px}.delete{color:#a32121}.notice{padding:12px;margin-bottom:15px;background:#d9f3df;color:#145a25}.error{background:#f9dddd;color:#8b1e1e}</style><style>body{margin:20px;background-color:#f2f2f2;color:black}main{max-width:none;margin:0}.panel{background-color:#fff;border:0;border-radius:0}th{background-color:blue;font-size:18px;border:1px solid black}td{font-size:16px;border:1px solid black;color:black}.back{background-color:blue;border-radius:4px;padding:8px 14px}.delete{color:red}.notice{color:green;border-radius:0}.error{color:red}</style></head><body><main><a class="back" href="index.php">Kembali ke Transaksi</a><section class="panel"><h1>Data Barang</h1><?php if($message): ?><div class="notice <?= $error?'error':'' ?>" role="alert"><?= htmlspecialchars($message) ?></div><?php endif; ?><table><tr><th>Kode</th><th>Nama</th><th>Harga</th><th>Stok</th><th>Supplier</th><th>Aksi</th></tr><?php while($row=$data->fetch_assoc()): ?><tr><td><?= htmlspecialchars($row['kode_barang']) ?></td><td><?= htmlspecialchars($row['nama_barang']) ?></td><td><?= rupiahBarang($row['harga']) ?></td><td><?= (int)$row['stok'] ?></td><td><?= htmlspecialchars($row['nama_supplier'] ?? '-') ?></td><td><a class="delete" href="barang.php?hapus=<?= (int)$row['id'] ?>" onclick="return confirm('Hapus barang ini?');">Hapus</a></td></tr><?php endwhile; ?></table></section></main></body></html>
